		[61861] = { -- ¡Y no vuelvas!
			{ "Busca un Garradesgarre errante (Roaming Shredclaw) eny pégale para marcarlo como tuyo. Si no lo marcas, no cuenta.", 2405, 60.76, 56.9 },
			"Llega un Desgarrador oportunista y se lo lleva volando. Súbete a tu montura y síguelo sin perderlo de vista; si lo pierdes, se reinicia.",
			{ "Va a su nido enAl llegar te dan el logro.", 2405, 43.96, 51.13 },
			"Notas de jugadores: también hay otro bicho que lo activa cerca del portal por el que llegas la primera vez a Tormenta del Vacío. Un jugador dice que en un personaje nuevo no le salió el desgarrador y sospecha que se necesita avanzar la campaña de Tormenta del Vacío; recomiendan hacerlo con tu personaje principal. Los nombres de los bichos son traducción no oficial (pueden cambiar en el juego).",
		},
		[61878] = { -- Marcado y capturado
			"Marcar como Forestal arcano",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61879] = { -- Tú la traes
			"Ganar como buscador marcando a todos en menos de 2 minutos",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61880] = { -- Son frías las sombras
			"Escondido sin que te encuentren 90 segundos seguidos",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61881] = { -- Escondido y escurridizo
			"Ser el último escondido sin marcar de tu equipo",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61882] = { -- Nulidad y evasión
			"Que te encuentren pero perder el estado sin que te marquen (quédate quieto)",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61883] = { -- Ahora no me ven...
			"Que no te marquen en el primer minuto (x3)",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61886] = { -- Colección completa
			"Las 8 mejoras: Salto disipador, Veloz, Zancafallas, Campo nulificador, Centinela de relojería, Sigilo, Crear señuelo, Pulso excentrimágico",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61887] = { -- Disfraz impecable
			"Los 9 anteriores",
			"Sugerencias (si vuelve): escóndete arriba, donde casi nadie mira; cuando te encuentren, quédate quieto en vez de correr.",
		},
		[61910] = { -- Mrglgrgl de Grglmrgl
			"Título: Mrglgrgl de Grglmrgl",
			"Las 3 historias del Rey Mrgl-Mrgl: Título: Mrglgrgl de Grglmrgl. Son tres historias viejas y una nueva:",
			"Refugio Aleta Invernal (Tundra Boreal, WotLK): 13 misiones, empieza con King Mrgl-Mrgl en el Refugio Aleta Invernal (costa de la Tundra Boreal); incluye escoltar a Lurgglbr (Escape from the Winterfin Caverns).",
			"Aguas turbias (Monte Alto, Legion): 6 misiones, empieza con That Guy in the Costume de Hemet Nesingwary.",
			"El loa de los múrlocs (Zul'Aman): con el Viejo Teo'zan; también cuenta para Residente de Zul'Aman.",
			"Las dos viejas se pueden hacer a cualquier nivel con Cronoviajes o al máximo.",
		},
		[61912] = { -- Anclaje defensivo
			"Evento de mundo en el suroeste de Tormenta del Vacío, cada 30 minutos.",
			"Con noventa por ciento alcanza: Terminar el evento con el anclaje de singularidad al 90 % de vida o más. No es de cuenta: cuenta por personaje",
			{ "Cómo funciona (Ciudadela de Tormentarion,:", 2405, 26.82, 67.89 },
			"Fase de construcción (5 minutos): pones defensas en puntos fijos del área; cada una cuesta Núcleos de Tormentarion (unos 10 por defensa). Los núcleos salen de los cofres del evento (Victorious Stormarion Cache) y otras actividades.",
			"3 oleadas de 3 minutos, con 30 segundos de descanso entre cada una. Los enemigos van directo al Anclaje de singularidad, ignoran a los jugadores si no los atacas, y si llegan explotan y le bajan vida.",
			"Si el anclaje se destruye, el evento termina y hay 10 minutos de espera.",
			"Para Anclaje defensivo: construye una de cada (Ojo negro · Pilar de choque · Barrera de luz · Mercenario de Umbramercado) en la fase de construcción. Es por personaje, así que guarda unos 40 núcleos. (por confirmar) Ninguna guía dice cuál punto de construcción da cada defensa: revisa qué ofrece cada punto al hacerle clic.",
			"Pon primero las defensas permanentes, porque frenan a los enemigos en las 3 oleadas; los consumibles solo sirven una vez.",
			"Coloca defensas en el camino de los enemigos; en algunos puntos bloquean el paso un rato.",
			"Hazlo cuando haya mucha gente en el evento y quédate cerca del anclaje matando lo que se escape.",
			"Con Xy'dax puedes comprar objetos de apoyo para el evento: Cracked Core (10 núcleos), Unstable Explosive Device (10) e Illegal Cosmic Emitter (30).",
		},
		[61913] = { -- Un problema singular
			"Evento de mundo en el suroeste de Tormenta del Vacío, cada 30 minutos.",
			"Con noventa por ciento alcanza: Terminar el evento con el anclaje de singularidad al 90 % de vida o más. No es de cuenta: cuenta por personaje",
			{ "Cómo funciona (Ciudadela de Tormentarion,:", 2405, 26.82, 67.89 },
			"Fase de construcción (5 minutos): pones defensas en puntos fijos del área; cada una cuesta Núcleos de Tormentarion (unos 10 por defensa). Los núcleos salen de los cofres del evento (Victorious Stormarion Cache) y otras actividades.",
			"3 oleadas de 3 minutos, con 30 segundos de descanso entre cada una. Los enemigos van directo al Anclaje de singularidad, ignoran a los jugadores si no los atacas, y si llegan explotan y le bajan vida.",
			"Si el anclaje se destruye, el evento termina y hay 10 minutos de espera.",
			"Para Anclaje defensivo: construye una de cada (Ojo negro · Pilar de choque · Barrera de luz · Mercenario de Umbramercado) en la fase de construcción. Es por personaje, así que guarda unos 40 núcleos. (por confirmar) Ninguna guía dice cuál punto de construcción da cada defensa: revisa qué ofrece cada punto al hacerle clic.",
			"Pon primero las defensas permanentes, porque frenan a los enemigos en las 3 oleadas; los consumibles solo sirven una vez.",
			"Coloca defensas en el camino de los enemigos; en algunos puntos bloquean el paso un rato.",
			"Hazlo cuando haya mucha gente en el evento y quédate cerca del anclaje matando lo que se escape.",
			"Con Xy'dax puedes comprar objetos de apoyo para el evento: Cracked Core (10 núcleos), Unstable Explosive Device (10) e Illegal Cosmic Emitter (30).",
		},
		[61916] = { -- Ira de los ren'dorei
			"Cazador de demonios elfo del Vacío",
			"Desbloquea el cazador de demonios elfo del Vacío (necesitas la raza aliada elfo del Vacío).",
			"Requisito: la historia En busca de la oscuridad en K'aresh (empieza con A Common Cause, con el Magíster Umbric).",
			"Empieza con The Pursuit Continues, del Magíster Umbric en Dornogal (también lo da el Mensajero Aelor, y algunas guías dicen que en Lunargenta). Nivel 80+; cualquier raza puede hacerla.",
			"Son 3 misiones ayudando a Leona a entrenar como cazadora de demonios en K'aresh; al terminar Trial of Wrath te dan el logro.",
		},
		[61942] = { -- Legado de los haranir
			"Armadura legada haranir",
			"Llega a nivel 50 con un haranir nuevo. Varias guías dicen que con un boost no cuenta: súbelo jugando. Recompensa: dos conjuntos de armadura legada, Har'alnor y Shul'ka (solo apariencia, solo haranir).",
		},
		[61959] = { -- Objetivo enfocado
			"Objetivo enfocado (Horda): Matar a los 15 campeones de la Horda: Moridora \"Nomueras\", \"Chispita\" Zikki, Atulash del eclipse, Caothun Toquesol, Hablatierra Ochomu, Giruma Sangrecuero, Machobala Bazza, Haz'waz el Tóxico, Celaryn la Frenética, Kirok el calcinado, Inquisidora Draeleth, Rin'zaka la Ventada, Siatra Alamágica, Taruka Manollama, Zindroz Escama Oscura",
			"Objetivo enfocado (Alianza): Matar a los 15 campeones de la Alianza: Andretta \"Golpeadora\" Nalee, Belanna Llamarada Brillante, Diabolista Inksie, Dawyn el Rabioso, Caladon Robavita, Anciano Tae Piepresto, Arcanista Aedmos, Falania Nocturnia, Oxidín \"Navaja\" Maddox, Nella Curoescoria, Lessia Golpazo, Exarca Thoss, Kozar Garradeplata, Theana Filoveraz, Ulfrik Brazorrecio",
			"Los campeones aparecen como enemigos del Campo de Entrenamiento (por confirmar). Haces el de la facción contraria a la tuya.",
			"Ojo: Según reportes de jugadores, algunos campeones tienen errores y no aparecen; puede que no se pueda completar hasta que lo arreglen.",
			"Sugerencias: las partidas de entrenamiento son cortas. Haz los de mapa juntos: en cada partida de Arathi o Gilneas toma banderas, y escribe /tren en cuanto entres.",
		},
		[61960] = { -- Tesoros de Bosque Canción Eterna
			"Mascota: Patahollín",
			{ "Llaves de la caja fuerte: Llave 1(a la derecha de la rampa de la torre sur de la Aldea Brisaveloz) · Llave 2(junto a una carreta sin'dorei rota) · Llave 3(junto a unas rocas cerca de un farol).", 2395, 37.64, 74.84 },
		},
		[61961] = { -- Fiebre de piedras rúnicas
			"Cómo funciona: le das Arcano latente a una piedra rúnica hasta cargarla; eso inicia una invasión. Después de varias oleadas sale el jefe, y matar al jefe es lo que cuenta. Solo se carga una piedra a la vez. El Arcano latente sale de las recompensas semanales de la Velada de Saltheril y de cofres por la zona.",
			"Los nombres de los jefes son traducción no oficial (pueden cambiar en el juego).",
		},
		[62057] = { -- Midnight: Las cumbres más altas
			"Midnight: Las cumbres más altas (meta)",
			"Pon telescopios en las cumbres de cada zona. No necesitas ningún objeto: salen en el minimapa como una banderita gris; al usarlos ves una escena corta y ganas +100 de reputación con la facción de la zona. La meta pide las 4 zonas.",
			{ "Bosque Canción Eterna: (por confirmar) el quinto punto", 2395, 40.4, 10.08 },
			{ "Zul'Aman: (por confirmar) el quinto punto", 2437, 53.03, 82.04 },
			{ "Harandar", 2413, 53.47, 58.6 },
			{ "Tormenta del Vacío", 2405, 41.75, 70.26 },
			"Sugerencia: haz los telescopios y la Cazahistoria juntos zona por zona: están cerca y los dos dan reputación de renombre.",
		},
		[62104] = { -- Cazahistoria de Midnight
			"21 objetos de historia. Salen en el minimapa con una lupa. Cada uno da +250 de reputación con la facción de renombre de su zona.",
		},
		[62105] = { -- Lysikas estaría orgulloso
			"Termina el encargo especial Precisión quirúrgica (Special Assignment: Precision Excision, Tormenta del Vacío) sin fallar ni un disparo. Por personaje.",
			"Solo cuando el encargo está activo; se desbloquea con 3 misiones de mundo de la zona.",
			"Vas en un Vermis de guerra que vuela por la Fortaleza de Tormentarion; apuntas a provisiones y enemigos.",
			"Dispara solo con la mira encima del objetivo y espera a que el vermis se acomode en cada zona. Si fallas uno, ya no cuenta esa vez.",
		},
		[62107] = { -- Un tren llamado entrenamiento
			"Usar /tren en cada mapa (Gilneas, Arathi, Lonjaplata). Sirve en cualquier momento, aun en la zona de salida",
		},
		[62109] = { -- Entrenamiento paciente
			"Ganar una partida sin morir",
		},
		[62110] = { -- Maestro cultural de Midnight
			"Fondos de gala",
			"El \"maestro cultural\" de la expansión. Pide: las 5 campañas de zona + Residente de Bosque Canción Eterna, Zul'Aman, Harandar y Tormenta del Vacío. Recompensa: Fondos de gala.",
		},
		[62111] = { -- Con las botas en la tierra: Cuenca de Arathi
			"Ganar 10 partidas con las 5 banderas bajo control",
		},
		[62112] = { -- Con las botas en la tierra: Batalla por Gilneas
			"Ganar 10 con las 3 banderas",
		},
		[62113] = { -- Con las botas en la tierra: Minas Lonjaplata
			"Ganar 10 sin que el enemigo capture ninguna vagoneta",
		},
		[62114] = { -- Estudio del terreno: Cuenca de Arathi
			"Tomar 50 banderas",
		},
		[62115] = { -- Estudio del terreno: La Batalla por Gilneas
			"Tomar 30 banderas",
		},
		[62116] = { -- Estudio del terreno: Minas Lonjaplata
			"Controlar 100 vagonetas",
		},
		[62120] = { -- Altar de bendiciones: Trol penitente
			"(por confirmar) Puul y Oe: deducido porque te faltan sus bendiciones en el logro 8.",
		},
		[62121] = { -- Altar de bendiciones: Devoto de los bufés sagrados
			"Transportabolsos: mamuts con la etiqueta <Reparador>, unos 13 puntos de aparición en la zona. Solo te dan la bendición si hablas con el de tu bendición activa, sin montura.",
		},
		[62122] = { -- Rareza diezmada
			"Decoración: Rostro de piedra amani colosal",
			"15 raros · +50 de reputación con la Tribu Amani cada uno (semanal).",
		},
		[62125] = { -- Tesoros de Zul'Aman
			"Juguete: Blindaje de pango",
			"Cada tesoro da +50 de reputación con la Tribu Amani.",
			{ "Haz clic en el alijo, dentro de las raíces de un árbol grande) para aceptar el desafío.", 2437, 46.9, 81.9 },
			"En cada urna, haz clic y mata al Elegido que sale:",
			{ "Akil'zon: Elegido de Akil'zon (bajando la montaña al sur del templo) · Garra de águila", 2437, 51.6, 84.9 },
			{ "Nalorakk: Elegido de Nalorakk (abajo de la entrada a la Guarida) · Diente de oso", 2437, 32.7, 83.5 },
			{ "Halazzi: Elegido de Halazzi (claro arriba de la cueva) · Garra de lince", 2437, 34.5, 33.5 },
			{ "Jan'alai: Elegido de Jan'alai (árbol quemado al sur del templo) · Pluma de dracohalcón", 2437, 54.8, 22.4 },
			"Regresa al alijo con los 4 y ábrelo. Si no abre, te falta uno.",
		},
		[62126] = { -- Tesoros de Tormenta del Vacío
			"Juguete: Señal de parcela interdimensional",
			"13 tesoros · cada uno da +50 de reputación con La Singularidad.",
		},
		[62130] = { -- Máxima depredación
			"Decoración: Cajón de almacenamiento domanaar abierto",
			"14 raros · +50 de reputación con La Singularidad cada uno (semanal). Pueden soltar las monturas Rayo de tormenta aumentado y Desgarrador sanguino.",
		},
		[62133] = { -- La emoción de la persecución
			"Escapa de la Presencia hambrienta al menos 60 segundos. Es un desgarrador gigante que persigue a quien vuela muy alto o muy lejos del mapa; vuela casi tan rápido como tu dracovuelo y si te alcanza mueres al instante.",
			"Activa un cronómetro: /stopwatch.",
			"Sube a un punto alto en la orilla del mapa (las montañas entre la Ciudadela de Obscurion y el Punto del Nexo Xenas sirven).",
			"Vuela hacia la orilla sin gastar cargas de dracovuelo. En cuanto salga el aviso \"Te persigue [Presencia hambrienta]\", arranca el cronómetro y huye.",
			"Vuela en ligera bajada para mantener Emoción de los cielos; usa Ascenso celestial para recuperar altura, Torbellino como acelerón de emergencia y Segundo aliento para recargar.",
			"Al pasar 60 segundos te dan el logro; ya puedes dejar que te alcance.",
			"Sugerencia: elige el talento Torbellino en el árbol de dracovuelo antes de intentarlo.",
		},
		[62134] = { -- La presa más letal
			"5 cacerías en Modo Guerra",
		},
		[62135] = { -- Que comience la fiesta
			"1 cacería de pesadilla en Modo Guerra",
		},
		[62136] = { -- Derroche de talento
			"Matar 50 jugadores en cacerías de pesadilla en Modo Guerra",
		},
		[62137] = { -- ¿Creen que corro peligro?
			"Superar 10 emboscadas",
		},
		[62138] = { -- Yo soy el peligro
			"Superar 100 emboscadas",
		},
		[62139] = { -- Cazador de Midnight
			"Una cacería en cada zona: Bosque Canción Eterna, Zul'Aman, Harandar, Tormenta del Vacío",
		},
		[62140] = { -- Cocina de pesadilla
			"Cocinar 100 cosas durante una cacería de pesadilla",
		},
		[62141] = { -- Pescaremos
			"Pescar 100 peces durante una cacería de pesadilla",
		},
		[62142] = { -- Derecho a réplica
			"50 Réplicas después de una emboscada",
		},
		[62143] = { -- Trampas que atrapan
			"Interactuar con 100 trampas en cacerías",
		},
		[62185] = { -- Inspiración artística
			"Decoración: Cojín de pintor de Lunargenta",
		},
		[62186] = { -- La fiesta debe continuar
			"Decoración: Bandeja de fiesta de Canción Eterna",
			"Se hace con la misión semanal Velada de Saltheril: cada semana invitas a una facción noble, así que toma mínimo 4 semanas.",
			"Sugerencia: no te saltes ninguna semana; si se te pasa una, el logro se retrasa otra semana.",
		},
		[62187] = { -- Sommelier del gran magíster
			{ "Se hace en la misión de mundo Encargo especial: El trago del gran magíster. Sale más o menos cada 28 días y dura 6-7 días; la siguiente se espera alrededor del 28 de noviembre (estimado).", 2395, 41.6, 60.5 },
			"Cómo funciona la misión: mata 10 murciélagos vinícolas malhumorados, prueba 3 vinos con los PNJ y elige 1 con Razia. Solo pruebas 3 de los 12 tragos por misión, así que necesitas 4 misiones (o 4 personajes la misma semana, porque es de cuenta).",
			"Antes de cada ronda abre el logro y escoge 3 tragos que no tengas.",
			"Habla con los PNJ antes de ir con Razia: el trago de Heron solo aparece en Razia después de hablar con Heron.",
			"Los encargos especiales se desbloquean al hacer 3 misiones de mundo de la zona.",
			"(por confirmar) En banda probablemente no cuenta (casi ninguna misión de mundo cuenta en banda desde BfA); hazla solo o en grupo de 5.",
			"(por confirmar) Por confirmar: si cuentan los 3 tragos que pruebas o solo el que eliges, y los nombres en español de los PNJ.",
		},
		[62188] = { -- Un asunto de raíz
			"Las coordenadas pueden variar un poco (ej. Kawayn 50.8 42.4). Chonon: 54.9 29.9.",
		},
		[62190] = { -- El alma de la fiesta
			"Reputación máxima con las 4 subfacciones de la Corte: Caballeros de sangre, Errantes, Magísteres, Sombras del Frontal · Montura: Dracohalcón umbrío",
		},
		[62192] = { -- Diplomático de Midnight
			"Renombre máximo con las 4 anteriores · Fondos de gala",
		},
		[62196] = { -- Combatiente de calabozos de Midnight
			"Los 8 calabozos son los del lanzamiento (no incluye Altar de Colmillos). De cuenta: puedes hacer el rol de sanador y tanque con otros personajes.",
		},
		[62199] = { -- No te lo olvides
			"Busca y únete a Chu'ke, el muñeco poseído. Criterios: Chu'ke encontrado · Chu'ke unido.",
			{ "Encuentra a Chu'ke: en la punta de roca que sale del mar a la derecha de la Aldea Amani'Zar (una islita en la esquina sureste del mapa),Aterriza arriba, háblale y elige la opción de cómo le pasó esto. Te pide un botón del tamaño de un ojo.", 2437, 59.24, 71.09 },
			{ "El botón: vuela a los Riscos Secacorteza (norte) y entra a la chocita de Kalika, la instructora de sastrería. Háblale y pide el botón; te señala un botón en el suelo, en la esquina del cuarto (otra guía dice que está atrás de una estatuilla de jade a la derecha de la choza). Recógelo.", 2437, 38.66, 23.78 },
			"Únete a Chu'ke: ve al lugar marcado lleno de muñequitos (también la llaman Guarida de Narak), camina hasta el tambor grande del fondo y habla con Chu'ke. Una guía da 37.80 90.11 (por confirmar).",
			"Las coordenadas de los pasos 2 y 3 todavía no están confirmadas; si no coinciden, sigue las marcas del juego.",
		},
		[62200] = { -- Mi pobre gnomito
			"Junta los 6 escritos del gnomo perdido. Sin coordenadas exactas; estas son las ubicaciones descritas, en el orden de la historia:",
			"No hay que hacerlos en orden.",
		},
		[62201] = { -- El sapo y las princesas
			"Usa /besar con los 5 sapos princesa (tenlos seleccionados al escribirlo). Ubicaciones:",
			"Son coordenadas de la comunidad; si no está exacto, búscalo cerca.",
		},
		[62202] = { -- Maratón Zarpánima
			"Ayuda al corredor zarpánima.",
			"Habla con Feevra (32.31 22.39) y toma al Cachorro de kapara (32.24 22.31). El efecto Escoltando al cachorro dura 30 minutos y se quita si te montas.",
			"Corre a pie hasta la isla del Santuario de Filo (51.52 32.79) y métete en el círculo marcado.",
			"Coordenadas del mapa de Zul'Aman.",
		},
		[62206] = { -- Surcabismos de Midnight III
			"Los 3 roles en nivel 11 · 50",
		},
		[62256] = { -- Gritando en Tormenta del Vacío
			"Cuenta para Luz en la penumbra",
		},
		[62260] = { -- ¡Eso es Aln, amigos!
			"Cuenta para Luz en la penumbra",
			"Lo que más tarda: Las leyendas nunca mueren y Cronista de los haranir necesitan mínimo 7 semanas, y Por suerte brillan necesita renombre 9 con los Hara'ti. Empieza esos primero.",
		},
		[62261] = { -- Canción perpetua
			"Cuenta para Luz en la penumbra (montura Alapétalo brillante)",
		},
		[62262] = { -- Campeón de la Corte de Lunargenta
			"Renombre 20 con la Corte de Lunargenta",
		},
		[62263] = { -- Campeón de la tribu Amani
			"Renombre 20 con la tribu Amani",
		},
		[62264] = { -- Campeón de los Hara'ti
			"Renombre 20 con los Hara'ti",
		},
		[62265] = { -- Campeón de la Singularidad
			"Renombre 20 con la Singularidad",
		},
		[62267] = { -- Un loa muy violento
			"Logro secreto: \"Experimenta la ira de Filo, loa de la infancia.\"",
