		[63630] = { -- Ataca la bóveda
			{ "Recompensa: montura Volutador venenoso. Entrada a las bóvedas:(Colmillo Occidental).", 2509, 31.1, 64.94 },
			"Cómo funciona la rotación: las Patrullas del templo (estrella) rotan cada 10 minutos; habla con el PNJ para un objetivo extra. Al completar un Ataque al templo (cabeza de serpiente) se abre una Incursión (10 minutos); al ganar la incursión salen los Rivales ancestrales.",
			"Vínculos rotos · Acaba con los exhaustos · Acaba con la prole de Ula'tek · Succionar veneno · Armas recuperadas · Aliento y bilis · Veneno coagulado · Hacia abajo · Venganza por los muertos · Polvo al polvo · La calma de los muertos · Descanso eterno.",
		},
		[63631] = { -- Tripulación del capitán Tokka
			"Rango máximo con Tokka (está en Reputación)",
			"Rango Tripulación jurasangre con el capitán Tokka",
			"Es una reputación por rangos, no de renombre.",
			"Extraño: 0",
			"Marinero condenado: 100",
			"Pescador maldito: 2700",
			"Pescador de veneno: 5300",
			"Tripulación jurasangre: 8400",
			{ "Cómo empezar: termina la campaña de la Isla Serpenteante (Pecado original). El capitán Tokka está en el campamento principaly da Pesca de veneno: la prueba está en el limo, que abre la cadena. La cadena te deja en Marinero condenado.", 2512, 57.21, 48.63 },
			{ "Diarias de Segundo oficial Sluggs o Brinedrinker Gills: (por confirmar) (no lo dicen las guías) · Locura de Tokka", 2512, 51.62, 49.84 },
			"Misión de mundo Pesca en mar abierto: 500 · Normalmente al noreste de la isla; sale más o menos cada semana",
			"10 objetos de misión que se pescan (una vez por tropa): 150 c/u · Los mismos de Tesoros de los malditos: ver Profesiones.md",
			{ "Recompensas (vendedor: Segundo oficial Sluggs,:", 2512, 51.64, 49.83 },
			"Marinero condenado: Adornos de vivienda y receta Plato de pez globo",
			"Pescador maldito: Receta de señuelo Devorador de estrellas enroscado y recetas de profesiones (150 Moxie)",
			"Pescador de veneno: Recetas Festín de conocimiento y Multiguarda de Tokka, adornos; mascota Elemental de veneno (100 de oro)",
			"Tripulación jurasangre: Caña La Cazadora Enroscada (6000 Marga). Con Filamento enroscado (se pesca con esa caña en la isla): montura Serpiente de isla marina (2500), arma de transfiguración Destripador envenenado (1000) y otras (500)",
			"Haz las diarias todos los días; con eso y la misión de mundo semanal llegas en unas semanas.",
			"Pescar los 10 objetos te da 1500 de un golpe y además el logro Tesoros de los malditos.",
			"La montura sale después del logro: primero la caña, luego juntar 2500 de Filamento.",
		},
		[63632] = { -- Trofeos tóxicos
			"Rango Trofeo con 8 peces",
			"Rango Trofeo (5 de 5) con los 8 peces que dicen \"Sí\" en la tabla de arriba. Los rangos son Guppy → Pececillo → Lucio → Tiburón → Trofeo y suben pescando más de ese pez; Se calculan unos 100 de cada uno, pero varía (a un jugador le salió Trofeo con el Pez fangoso en pocas pescas).",
			"Los 3 comunes (Mortipez, Dardero, Tlhapi) suben solos mientras pescas lo demás.",
			"Haz el Cabeza de serpiente y el Devoraestrellas juntos en las Bóvedas.",
			"Para el Enjambrista, sigue las Oleadas de maldición y ve directo a las Aguas malditas en cuanto termine una.",
		},
		[63633] = { -- Una pila de serpientes
			"Mascota: Claqui",
			"Dale a Claqui (Ki'clak) 5 bocadillos con la misión de mundo Atracón de Claqui (Isla Serpenteante). Mascota: Claqui. De cuenta.",
			{ "Desbloqueo: habla con Olawu, haz Ghosts of the Ring (Desembarco de Tokka) y termina No te abatas del miedo.", 2512, 58.5, 47.2 },
			"Cuando salga la misión (fuera de banda): mata a los fantasmas marcados hasta tener 10 Ectoplasmas arremolinados (69.6 56.4), habla con Mab'jul y elige la opción del bocadillo. Dáselo a Claqui (69.3 52.1).",
			"Comprar bocadillos al vendedor no cuenta. Se necesitan 5 misiones (varias semanas).",
		},
		[63634] = { -- ¿De dónde lo sacaste?
			"Hablar con el Capitán Tokka con la caña La cazadora enrollada equipada. Cómprala a Sluggs, equípala, habla con Tokka y elige la opción nueva para enseñársela. Ojo: Si tienes oculto el equipo de profesión, a veces no cuenta. Si no sale, ve a Lunargenta y vuelve a hablar con él",
		},
		[63635] = { -- Pruebas terribles de Tokka
			"Los logros 2, 3, 4 y 5 · Título: Marinero jurasangre",
