		[63636] = { -- Corrosión completa
			{ "El Altar de corrosión está en el Bastión Amani, con Er'inye. Cada talento cuesta Corrosión espiritual, que sale de:", 2509, 51.2, 62.6 },
			"Gastar Monedas corrosivas con Er'inye.",
			"Los 4 descubrimientos (1 punto cada uno y desbloquean una elección).",
			"Renombre 8 y 14 con las Fuerzas de Zul'jarra.",
			{ "Amuleto med'jai perdido: Amuleto disipador · Relicario de Jin'tal, Mausoleo Profanado", 2638, 36.73, 24.73 },
			{ "Pluma de Tok'jara: Lupa espiritual · Repisa del Sello de la Ira, cerca de la entrada al Abismo Venenoso", 2509, 48.46, 25.8 },
			"Pata de lince momificada: Llave corroída · Cofre desgastado por el veneno, 5 lugares posibles: 52.51 53.85 · 41.96 53.58 · 42.51 12.01 · 47.48 37.59 · 53.69 18.18 (#2509)",
			{ "Ojo de Szarith: Cuchillo de extirpación · Charco de veneno del cuarto de atrás de los Bajos Fondos", 2613, 68.52, 15.86 },
			"Los objetos que necesitas salen de Ataques, Incursiones y Rivales (no se sabe cuál de cada uno). Los nombres de descubrimientos y objetos son traducción no oficial (pueden cambiar en el juego). (por confirmar)",
		},
